// pp:data-source live

var exportTerminalSuccess = map[string]bool{
	"COMPLETED": true, "COMPLETE": true, "SUCCESS": true, "SUCCEEDED": true, "DONE": true,
}
var exportTerminalFailure = map[string]bool{
	"FAILED": true, "ERROR": true, "CANCELLED": true, "CANCELED": true,
}

type exportStatusEnvelope struct {
	Data struct {
		ExportID int    `json:"exportId"`
		Status   string `json:"status"`
	} `json:"data"`
}

// newNovelExportsWatchCmd polls /v2/exports/status for one export until it
// reaches a terminal state, then exits 0 on success or non-zero on failure.
// Zapmail has no list-exports endpoint, so this watches a single known export
// id (the value returned when you started the export).
func newNovelExportsWatchCmd(flags *rootFlags) *cobra.Command {
	var exportID int
	var interval time.Duration
	var timeout time.Duration

	cmd := &cobra.Command{
		Use:   "watch",
		Short: "Poll one export to completion and exit non-zero if it fails",
		Long: strings.Trim(`
Poll /v2/exports/status for a single export id until it reaches a terminal
state, printing each status transition. Exits 0 when the export completes and
non-zero when it fails or times out, so you can gate a script on it.

Pass the export id returned by 'exports mailboxes'. Zapmail has no
list-exports endpoint, so this watches one known export at a time.
`, "\n"),
		Example:     "  zapmail-pp-cli exports watch --export-id 12345",
		Annotations: map[string]string{"mcp:read-only": "true", "pp:typed-exit-codes": "0,1"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if exportID == 0 && !flags.dryRun && !cliutil.IsVerifyEnv() {
				return fmt.Errorf("--export-id is required (the id returned by 'exports mailboxes')")
			}
			if cliutil.IsVerifyEnv() {
				fmt.Fprintf(cmd.OutOrStdout(), "would watch export %d\n", exportID)
				return nil
			}
			if dryRunOK(flags) {
				return nil
			}
			c, err := flags.newClient()
			if err != nil {
				return err
			}
			deadline := time.Now().Add(timeout)
			params := map[string]string{"exportId": fmt.Sprintf("%d", exportID)}
			var last string
			for {
				raw, err := c.GetNoCache(cmd.Context(), "/v2/exports/status", params)
				if err != nil {
					return classifyAPIError(err, flags)
				}
				var env exportStatusEnvelope
				if err := json.Unmarshal(raw, &env); err != nil {
					return fmt.Errorf("parsing export status: %w", err)
				}
				status := strings.ToUpper(strings.TrimSpace(env.Data.Status))
				if status != last {
					fmt.Fprintf(cmd.ErrOrStderr(), "export %d: %s\n", exportID, status)
					last = status
				}
				if exportTerminalSuccess[status] {
					return printJSONFiltered(cmd.OutOrStdout(), env.Data, flags)
				}
				if exportTerminalFailure[status] {
					return fmt.Errorf("export %d ended in status %s", exportID, status)
				}
				if time.Now().After(deadline) {
					return fmt.Errorf("export %d did not complete within %s (last status: %s)", exportID, timeout, status)
				}
				select {
				case <-cmd.Context().Done():
					return cmd.Context().Err()
				case <-time.After(interval):
				}
			}
		},
	}
	cmd.Flags().IntVar(&exportID, "export-id", 0, "Export id to watch (from 'exports mailboxes')")
	cmd.Flags().DurationVar(&interval, "interval", 5*time.Second, "Polling interval")
	cmd.Flags().DurationVar(&timeout, "timeout", 5*time.Minute, "Give up after this long")
	return cmd
}
